<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['full_name']??''));if($name==='')$error='Nama lengkap wajib diisi.';else{$pdo->beginTransaction();try{$pdo->prepare('UPDATE users SET full_name=?,phone=?,address=?,bio=?,updated_at=NOW() WHERE id=?')->execute([$name,trim((string)($_POST['phone']??''))?:null,trim((string)($_POST['address']??''))?:null,trim((string)($_POST['bio']??''))?:null,$user['id']]);$pdo->prepare('INSERT INTO teacher_profiles(user_id,full_name,nip,phone,address,bio)VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),nip=VALUES(nip),phone=VALUES(phone),address=VALUES(address),bio=VALUES(bio),updated_at=NOW()')->execute([$user['id'],$name,trim((string)($_POST['nip']??''))?:null,trim((string)($_POST['phone']??''))?:null,trim((string)($_POST['address']??''))?:null,trim((string)($_POST['bio']??''))?:null]);$pdo->commit();audit_event('teacher_profile_updated','success',$user['id'],['target'=>$user['username']]);flash('success','Profil Guru berhasil diperbarui.');redirect('guru/profile.php');}catch(Throwable $e){$pdo->rollBack();$error='Profil gagal disimpan.';}}}$stmt=$pdo->prepare('SELECT u.*,p.nip FROM users u LEFT JOIN teacher_profiles p ON p.user_id=u.id WHERE u.id=?');$stmt->execute([$user['id']]);$profile=$stmt->fetch();$pageTitle='Profil Guru';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Identitas Pengajar</p><h1 class="page-title">Profil Guru</h1><p class="page-description">Perbarui identitas, kontak, alamat, dan foto profil Guru.</p></div></div><?php if($error):?><div class="alert alert-error"><?= e($error) ?></div><?php endif;?><section class="grid grid-2"><article class="card"><h2 class="card-title">Biodata Guru</h2><form method="post" class="form-grid"><?= csrf_field() ?><div class="field full"><label>Nama Lengkap</label><input class="input" name="full_name" value="<?= e($profile['full_name']) ?>" required></div><div class="field"><label>NIP</label><input class="input" name="nip" value="<?= e($profile['nip']) ?>"></div><div class="field"><label>Telepon</label><input class="input" name="phone" value="<?= e($profile['phone']) ?>"></div><div class="field full"><label>Alamat</label><textarea class="textarea" name="address"><?= e($profile['address']) ?></textarea></div><div class="field full"><label>Bio</label><textarea class="textarea" name="bio"><?= e($profile['bio']) ?></textarea></div><button class="btn btn-primary field full">Simpan Profil</button></form></article><article class="card"><h2 class="card-title">Foto Profil</h2><?php if($profile['photo_url']):?><img src="<?= url($profile['photo_url']) ?>" alt="Foto Guru" style="width:140px;height:140px;object-fit:cover;border-radius:50%;margin-bottom:18px"><?php else:?><div class="avatar" style="width:140px;height:140px;font-size:48px;margin-bottom:18px"><?= e(strtoupper($profile['full_name'][0])) ?></div><?php endif;?><form action="<?= url('api/upload/photo.php') ?>" method="post" enctype="multipart/form-data" data-ajax class="grid"><?= csrf_field() ?><input type="hidden" name="type" value="teacher"><input class="input" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><button class="btn btn-soft">Unggah Foto Maksimal 2 MB</button></form></article></section><?php require ROOT_PATH.'/includes/footer.php';?>

